import pathlib, struct

def atom_iter(data, start, end):
    pos = start
    while pos + 8 <= end:
        size = struct.unpack('>I', data[pos:pos+4])[0]
        typ = data[pos+4:pos+8]
        if size == 0: size = end - pos
        if size < 8: break
        yield typ, pos, size
        pos += size

def has_audio(path):
    data = path.read_bytes()
    # 只在 moov 里找 hdlr，handler_type == b'soun' 即音轨
    for typ, pos, size in atom_iter(data, 0, len(data)):
        if typ == b'moov':
            moov_end = pos + size
            for t2, p2, s2 in atom_iter(data, pos+8, moov_end):
                if t2 == b'trak':
                    for t3, p3, s3 in atom_iter(data, p2+8, p2+s2):
                        if t3 == b'mdia':
                            for t4, p4, s4 in atom_iter(data, p3+8, p3+s3):
                                if t4 == b'hdlr':
                                    htype = data[p4+16:p4+20]
                                    if htype == b'soun':
                                        return True
    return False

base = pathlib.Path('/Users/honlnk/project/short-drama-web/apps/api/uploads/videos')
files = sorted(base.glob('drama-*/ep-*.mp4'))
a = sum(1 for f in files if has_audio(f))
print(f'共 {len(files)} 个视频，含音轨 {a} 个')
for f in files:
    print(('有声' if has_audio(f) else '无声'), f.relative_to(base.parent.parent.parent.parent))
